import json
from pathlib import Path
root=Path(__file__).parent
cases=[]
def case(id,stage,context,prompt,options,answer,why,objective):
 cases.append(dict(id=id,stage=stage,context=context,prompt=prompt,options=options,answer=answer,why=why,objective=objective,review_status='Source-informed draft; independent educator review pending'))
case('H01','Notice','You are meeting a Hindi-speaking workshop facilitator for the first time. You want a respectful opening.','Which form is the best starting point in this scene?',['आप · āp','तुम · tum','तू · tū'],0,'आप is the respectful starting choice here. A later invitation to use another form could change the interaction. This is a choice for this scene, not a rule about every teacher.','Select a respectful opening from explicit context.')
case('H02','Notice','Two adult friends have explicitly agreed that they address each other as तुम.','Which form follows their shared preference?',['तू · tū','आप · āp','तुम · tum'],2,'Use the relationship information provided: these friends chose तुम. Friendship alone would not tell us enough.','Use an expressed preference rather than a stereotype.')
case('H03','Notice','Two siblings tell you that they use तू affectionately with each other.','What does तू express in this particular scene?',['It must be an insult.','It can express intimacy here.','It is the required form for all siblings.'],1,'The stated relationship makes an intimate interpretation appropriate. The same form can carry a different force elsewhere; do not generalize from one household.','Interpret a form within a stated relationship.')
case('H04','Notice','You know only that two people are cousins. You have not heard how they address each other.','Can you tell which form they use with each other?',['They must use तुम.','They must use तू.','There is not enough information.'],2,'A family relationship alone does not establish a preferred form. Listen to the speakers or ask about their preference.','Recognize when relationship information is insufficient.')
case('H05','Practice','The lesson is practising standard Hindi agreement with आप. The meaning is “Where are you?”','Complete: आप कहाँ ___?',['हो','हैं','है'],1,'For the standard pattern taught in this lesson, pair आप with हैं: आप कहाँ हैं? The target is agreement, not a judgment about all regional speech.','Match आप with हैं in the taught pattern.')
case('H06','Practice','The lesson is practising standard Hindi agreement with तुम. The meaning is “Where are you?”','Complete: तुम कहाँ ___?',['हैं','है','हो'],2,'In this taught pattern: तुम कहाँ हो? Keep the pronoun fixed so the exercise isolates one agreement choice.','Match तुम with हो in the taught pattern.')
case('H07','Practice','You are reading a dialogue between the siblings who use तू with each other. The meaning is “Where are you?”','Complete: तू कहाँ ___?',['है','हो','हैं'],0,'The standard agreement pattern here is तू कहाँ है? Recognizing the pattern does not mean recommending तू to a stranger.','Match तू with है in the taught pattern.')
case('H08','Practice','A friend has asked you to address them as तुम. You are practising the standard pattern for “Where are you?”','Which sentence follows both that preference and the pattern?',['तुम कहाँ हैं? · tum kahā̃ haĩ?','तुम कहाँ हो? · tum kahā̃ ho?','तुम कहाँ है? · tum kahā̃ hai?'],1,'तुम कहाँ हो? combines the requested form with the agreement pattern taught here.','Combine an expressed preference with the taught agreement pattern.')
case('H09','Transfer','A new colleague says, “Please use तुम with me.” You want to follow that preference.','Which question fits the stated preference and the taught agreement pattern?',['तुम कहाँ हो? · tum kahā̃ ho?','आप कहाँ है? · āp kahā̃ hai?','तू कहाँ हो? · tū kahā̃ ho?'],0,'तुम कहाँ हो? follows the expressed preference and the agreement pattern. The invitation supplies context that a job title alone could not.','Combine a social cue with grammatical agreement.')
case('H10','Transfer','You are beginning a respectful conversation with an unfamiliar visitor. No informal preference has been established.','Choose the best starting question for this scene.',['तू कहाँ है? · tū kahā̃ hai?','तुम कहाँ हो? · tum kahā̃ ho?','आप कहाँ हैं? · āp kahā̃ haĩ?'],2,'आप कहाँ हैं? is the respectful starting question in this scene. Further context could support other choices later.','Apply the lesson to a new first meeting.')
case('H11','Transfer','A friend tells you that their close family members address each other as आप.','What can you reasonably conclude?',['They cannot be close.','This family uses आप in close relationships.','They have made a grammar mistake.'],1,'Respectful address and closeness can coexist. One form cannot tell you everything about a relationship.','Interpret a stated practice without treating a teaching shortcut as a universal rule.')
case('H12','Transfer','You are asked how you would address a new person, but you are given no setting, relationship, or preference.','What would help you make a better choice?',['Knowing the situation and how the person prefers to be addressed.','Knowing only how many letters each pronoun has.','Assuming everyone prefers the form your friends use.'],0,'Context and expressed preference help you choose. Your own familiar pattern is useful experience, but it is not a universal rule.','Transfer context-sensitive judgment to an unfamiliar interaction.')
script=[]
for i,(glyph,target,opts,ans) in enumerate([
 ('का','kā',['ka','kā','ki'],1),('कि','ki',['ik','kī','ki'],2),('की','kī',['kī','ki','ka'],0),
 ('मा','mā',['mi','mā','ma'],1),('मि','mi',['im','mī','mi'],2),('मी','mī',['mī','mi','mā'],0),
 ('पा','pā',['pi','pa','pā'],2),('पि','pi',['pi','ip','pī'],0),('पी','pī',['pi','pī','pā'],1),
 ('ना','nā',['nā','ni','na'],0),('नि','ni',['nī','in','ni'],2),('नी','nī',['ni','nī','nā'],1)]):
 script.append(dict(id=f'S{i+1:02}',glyph=glyph,target=target,options=opts,answer=ans,stage='Guided' if i<6 else 'Transfer',why=f'{glyph} is read {target} in this isolated syllable exercise. '+('The short-i sign appears to the left but is read after the consonant.' if target.endswith('i') else 'The vowel sign changes the vowel in the syllable.'),review_status='Source-informed draft; independent educator review pending'))
fixtures=[
 dict(id='Q01',title='A confident answer to an incomplete question',draft='Translate “you” into Hindi. Correct answer: तुम. Reject all other answers.',issue='Missing relationship and setting; falsely narrow answer key.',revision='At a first meeting, you want a respectful way to address an unfamiliar adult. Choose the best starting form: आप / तुम / तू.',decision='Revise',dimensions=['Context','Accepted answers'],reason='Make the target interpretable before scoring it.'),
 dict(id='Q02',title='The universal family',draft='Always use तू with family members.',issue='An absolute cultural rule erases variation between families and relationships.',revision='In this dialogue, two siblings have told us they use तू with each other. Interpret its use in that scene; do not generalize to all families.',decision='Revise',dimensions=['Variation','Context'],reason='Give a particular relationship; remove the universal claim.'),
 dict(id='Q03',title='The polite pronoun, the wrong agreement',draft='Target: standard agreement. Model answer: आप कहाँ हो?',issue='The model answer conflicts with the standard pattern this item is teaching.',revision='For this standard-pattern exercise, use आप कहाँ हैं? Add a reviewer note that real-world variation requires contextual judgment.',decision='Revise',dimensions=['Accuracy','Objective'],reason='Keep the target pattern consistent without declaring all other usage illegitimate.'),
 dict(id='Q04',title='A vowel sign takes a wrong turn',draft='कि is pronounced ik because the vowel mark appears first.',issue='It mistakes visual position for spoken order.',revision='कि is ki. The short-i sign appears on the left of the consonant, but the vowel is read after it.',decision='Revise',dimensions=['Accuracy','Explanation'],reason='Correct the underlying misconception, not just the selected option.'),
 dict(id='Q05',title='A reading lesson becomes a vocabulary test',draft='Objective: distinguish ि and ी. Task: translate an unfamiliar paragraph and infer the speaker’s mood.',issue='The task adds vocabulary and inference demands unrelated to the narrow objective.',revision='First distinguish कि and की. Then apply the same contrast to मि and मी. Assess paragraph comprehension separately.',decision='Revise',dimensions=['Objective','Difficulty'],reason='Change one demand at a time before increasing task complexity.'),
 dict(id='Q06',title='An item with a defensible target',draft='Objective: standard agreement with तुम. Prompt: Complete तुम कहाँ ___? Options: है / हो / हैं. Key: हो. Feedback: In this pattern, तुम pairs with हो.',issue='No intentionally planted defect in this fixture; scope and answer key are explicit.',revision='Retain the item for independent educator review. Approval in this demonstration is not production sign-off.',decision='Approve',dimensions=['Accuracy','Objective'],reason='A review system must allow sound items through, not only find faults.')]
data=dict(version='1.0',status='Independent portfolio prototype, not affiliated with Duolingo. AI-assisted drafts; external educator review and learner study pending.',pronoun_cases=cases,script_items=script,review_fixtures=fixtures)
(root/'content.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
template=(root/'template.html').read_text()
(root/'dist'/'indian-languages-lab.html').write_text(template.replace('/*DATA*/',json.dumps(data,ensure_ascii=False)))
(root/'dist'/'index.html').write_text((root/'dist'/'indian-languages-lab.html').read_text())
